  "supportive_card_ids": ["C127","C108","C113","C128","C101","C98","C120","C104","C109","C141","C130","C117","C137","C140","C107","C04","C07","C12","C29","C42","C03","C20"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C04","C07","C12","C29","C42","C03","C20","C127","C108","C128","C98","C120"],
  "claims": [
    {
      "claim": "L4 absorption records show fluoroquinolones with the same zwitterionic acid-amine pharmacophore are almost completely absorbed in humans: levofloxacin (C127), ofloxacin (C108, C113, C128 at 85-95%), and the ofloxacin-levofloxacin-pefloxacin-enoxacin group (C113, C132, C116, C134).",
      "card_ids": ["C127","C108","C113","C128","C132","C116","C134"]
    },
    {
      "claim": "Ciprofloxacin, a close C7-amine fluoroquinolone, shows 78% absorption from the proximal intestine (C98) and estimated fraction absorbed above 80% for most subjects from an oral solution (C120), with >90% in vivo dissolution (C117) and 10 mg/mL aqueous solubility (C141, C130).",
      "card_ids": ["C98","C120","C117","C141","C130"]
    },
    {
      "claim": "Fleroxacin, another C7-piperazine fluoroquinolone, is rapidly and completely absorbed from the GI tract (C101), and enoxacin is very soluble at gastric pH (C137), supporting the absorption component for this chemotype.",
      "card_ids": ["C101","C137"]
    },
    {
      "claim": "L4 solubility values for fluoroquinolones are in the mg/mL range (ofloxacin 6.62 mg/mL, norfloxacin salts 3.9-9.8 mg/mL, ciprofloxacin HCl 10 mg/mL), showing that full ionization does not prevent dissolution or absorption in this class.",
      "card_ids": ["C109","C105","C99","C141","C130"]
    },
    {
      "claim": "L1/L2 direct F measurements remain the strongest endpoint evidence: moxifloxacin 86-99%, trovafloxacin 87.6-88%, levofloxacin and ofloxacin approaching 100%, antofloxacin high, and norfloxacin mean 40%; all fluoroquinolone F values exceed 20%.",
      "card_ids": ["C04","C42","C03","C07","C12","C29","C09","C20"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C127","C108","C113","C128","C101","C98","C120","C104","C109","C141","C130","C117","C137","C140","C107"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No query-specific permeability, efflux, or first-pass data are available; L4 records are for other fluoroquinolones.",
    "No query-specific formulation, dose, or prandial-state data are available.",
    "Some L4 records are from non-human species (rat, dog, pig) or non-fluoroquinolone drugs and are only indirectly transferable.",
    "The C7 spiro-aminopyrrolidine, C8-Cl, and N1-fluorocyclopropyl combination has no exact-match experimental record."
  ],
  "decision_summary": "L4 intestinal absorption and solubility evidence is directionally supportive: fluoroquinolones sharing the query's zwitterionic acid-amine core are almost completely absorbed in humans (levofloxacin, ofloxacin, fleroxacin), ciprofloxacin shows 78-80%+ fraction absorbed with mg/mL solubility, and no L4 record indicates poor absorption for this chemotype. Combined with L1/L2 direct F values for fluoroquinolones all above 20% and L3 oral/IV exposure support, the prediction remains high and confidence is strengthened. The physicochemical prior of full ionization is not affirmative evidence of F below 20% because the class achieves high absorption despite it."
}

